after:
  OrchestrationV2Run, OrchestrationV2StoredEvent, OrchestrationV2DomainEvent,
  OrchestrationV2ThreadShellSnapshot, ProviderApprovalDecision, TurnItemId,
} from "@t3tools/contracts";
import type { TerminalOutputState } from "@t3tools/shared/terminalOutput";

// Test-only source types. No Orchestrator, ProjectStore or runtime-policy service is imported.
type RuntimePolicyV2Override = {
  readonly cwd?: string;
  readonly approvalPolicy?: unknown;
  readonly sandboxPolicy?: unknown;
  readonly reasoningEffort?: string;
};
type OrchestratorV2ScenarioStep =
  | { readonly type: "dispatch"; readonly command: OrchestrationV2Command; readonly await?: boolean; readonly key?: string }
  | { readonly type: "advance_clock"; readonly duration: Duration.Input }
  | { readonly type: "await"; readonly key: string }
  | { readonly type: "await_all" }
  | { readonly type: "await_thread_idle" | "await_no_background_work"; readonly threadId: ThreadId }
  | { readonly type: "await_run_steerable"; readonly threadId: ThreadId; readonly runId: OrchestrationV2Run["id"] }
  | { readonly type: "await_run_status" | "finish_held_run"; readonly threadId: ThreadId; readonly runId: OrchestrationV2Run["id"]; readonly status: OrchestrationV2Run["status"] }
  | { readonly type: "await_run_turn_item"; readonly threadId: ThreadId; readonly runId: OrchestrationV2Run["id"]; readonly itemType: OrchestrationV2TurnItem["type"] }
  | { readonly type: "release_replay_gate_after_waiting"; readonly label: string; readonly threadId: ThreadId; readonly runId: OrchestrationV2Run["id"] }
  | { readonly type: "release_replay_gate"; readonly label: string }
  | { readonly type: "capture_shell_snapshot"; readonly key: string }
  | { readonly type: "respond_to_next_runtime_request"; readonly threadId: ThreadId; readonly commandId: CommandId; readonly decision?: ProviderApprovalDecision; readonly answers?: ProviderUserInputAnswers; readonly shellSnapshotKeyWhilePending?: string };
interface OrchestratorV2ScenarioResult {
  readonly storedEvents: ReadonlyArray<OrchestrationV2StoredEvent>;
  readonly domainEvents: ReadonlyArray<OrchestrationV2DomainEvent>;
  readonly projections: ReadonlyMap<ThreadId, OrchestrationV2ThreadProjection>;
  readonly shellSnapshot: OrchestrationV2ThreadShellSnapshot;
  readonly capturedShellSnapshots: ReadonlyMap<string, OrchestrationV2ThreadShellSnapshot>;
  readonly commandOutput?: ReadonlyMap<TurnItemId, { readonly chunks: number; readonly output: TerminalOutputState }>;
}
